#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>
#include "cJSON.h"
#include "lodepng.h"

static std::string readFile(const char* path) {
    FILE* f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    std::string s;
    s.resize((size_t)n);
    size_t r = fread(&s[0], 1, (size_t)n, f);
    (void)r;
    fclose(f);
    return s;
}

static float* load_param(cJSON* root, const char* name, int& rows, int& cols) {
    cJSON* node = cJSON_GetObjectItem(root, name);
    cJSON* shape = cJSON_GetObjectItem(node, "shape");
    int nd = cJSON_GetArraySize(shape);
    int d0 = cJSON_GetArrayItem(shape, 0)->valueint;
    int d1 = (nd > 1) ? cJSON_GetArrayItem(shape, 1)->valueint : 1;
    rows = d0; cols = d1;
    int total = d0 * d1;
    float* out = new float[total];
    cJSON* data = cJSON_GetObjectItem(node, "data");
    for (int i = 0; i < total; i++) {
        out[i] = (float)cJSON_GetArrayItem(data, i)->valuedouble;
    }
    return out;
}

static void linear(const float* W, const float* b, const float* x, int rows, int cols, float* out) {
    for (int i = 0; i < rows; i++) {
        float s = b[i];
        const float* wr = W + (size_t)i * cols;
        for (int j = 0; j < cols; j++) s += wr[j] * x[j];
        out[i] = s;
    }
}

static inline float relu(float v) { return v > 0.0f ? v : 0.0f; }

int main(int argc, char** argv) {
    if (argc < 3) {
        fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]);
        return 1;
    }
    std::string wpath = argv[1];
    const char* ipath = argv[2];

    std::string js = readFile(wpath.c_str());
    cJSON* root = cJSON_Parse(js.c_str());
    if (!root) { fprintf(stderr, "bad json\n"); return 1; }

    int r1, c1, r2, c2, r3, c3, r4, c4, r5, c5, r6, c6;
    float* W1 = load_param(root, "input_layer.weight", r1, c1);
    float* b1 = load_param(root, "input_layer.bias", r4, c4);
    float* W2 = load_param(root, "hidden_layer.weight", r2, c2);
    float* b2 = load_param(root, "hidden_layer.bias", r5, c5);
    float* W3 = load_param(root, "output_layer.weight", r3, c3);
    float* b3 = load_param(root, "output_layer.bias", r6, c6);

    std::vector<unsigned char> image;
    unsigned w, h;
    unsigned err = lodepng::decode(image, w, h, ipath);
    if (err) { fprintf(stderr, "png error %u: %s\n", err, lodepng_error_text(err)); return 1; }

    int N = (int)(w * h);
    float* x = new float[N];
    for (int i = 0; i < N; i++) {
        unsigned char pix = image[(size_t)i * 4 + 0];
        x[i] = (float)(((double)pix / 255.0 - 0.1307) / 0.3081);
    }

    float* h1 = new float[r1];
    float* h2 = new float[r2];
    float* out = new float[r3];

    linear(W1, b1, x, r1, c1, h1);
    for (int i = 0; i < r1; i++) h1[i] = relu(h1[i]);
    linear(W2, b2, h1, r2, c2, h2);
    for (int i = 0; i < r2; i++) h2[i] = relu(h2[i]);
    linear(W3, b3, h2, r3, c3, out);

    int pred = 0;
    for (int i = 1; i < r3; i++) if (out[i] > out[pred]) pred = i;

    printf("%d", pred);

    size_t sl = wpath.find_last_of('/');
    std::string dir = (sl == std::string::npos) ? std::string("./") : wpath.substr(0, sl + 1);
    std::string predp = dir + "prediction.txt";
    FILE* pf = fopen(predp.c_str(), "wb");
    if (pf) { fprintf(pf, "%d", pred); fclose(pf); }

    return 0;
}
