    if (argc < 3) {
        fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]);
        return 1;
    }
    std::string wpath = argv[1];
    const char* ipath = argv[2];

    std::string js = readFile(wpath.c_str());
    cJSON* root = cJSON_Parse(js.c_str());
    if (!root) { fprintf(stderr, "bad json\n"); return 1; }

    int r1, c1, r2, c2, r3, c3, r4, c4, r5, c5, r6, c6;
    float* W1 = load_param(root, "input_layer.weight", r1, c1);
    float* b1 = load_param(root, "input_layer.bias", r4, c4);
    float* W2 = load_param(root, "hidden_layer.weight", r2, c2);
    float* b2 = load_param(root, "hidden_layer.bias", r5, c5);
    float* W3 = load_param(root, "output_layer.weight", r3, c3);
    float* b3 = load_param(root, "output_layer.bias", r6, c6);

    std::vector<unsigned char> image;
    unsigned w, h;
    unsigned err = lodepng::decode(image, w, h, ipath);
    if (err) { fprintf(stderr, "png error %u: %s\n", err, lodepng_error_text(err)); return 1; }

