static std::string readFile(const char* path) {
    FILE* f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    std::string s;
    s.resize((size_t)n);
    size_t r = fread(&s[0], 1, (size_t)n, f);
    (void)r;
    fclose(f);
    return s;
}

static float* load_param(cJSON* root, const char* name, int& rows, int& cols) {
    cJSON* node = cJSON_GetObjectItem(root, name);
    cJSON* shape = cJSON_GetObjectItem(node, "shape");
    int nd = cJSON_GetArraySize(shape);
    int d0 = cJSON_GetArrayItem(shape, 0)->valueint;
    int d1 = (nd > 1) ? cJSON_GetArrayItem(shape, 1)->valueint : 1;
    rows = d0; cols = d1;
    int total = d0 * d1;
    float* out = new float[total];
    cJSON* data = cJSON_GetObjectItem(node, "data");
    for (int i = 0; i < total; i++) {
        out[i] = (float)cJSON_GetArrayItem(data, i)->valuedouble;
    }
    return out;
}

static void linear(const float* W, const float* b, const float* x, int rows, int cols, float* out) {
    for (int i = 0; i < rows; i++) {
        float s = b[i];
        const float* wr = W + (size_t)i * cols;
        for (int j = 0; j < cols; j++) s += wr[j] * x[j];
        out[i] = s;
    }
}

static inline float relu(float v) { return v > 0.0f ? v : 0.0f; }

