    cJSON* root = cJSON_Parse(js.c_str());
    if (!root) { fprintf(stderr, "bad json\n"); return 1; }

    int r1, c1, r2, c2, r3, c3, r4, c4, r5, c5, r6, c6;
    float* W1 = load_param(root, "input_layer.weight", r1, c1);
    float* b1 = load_param(root, "input_layer.bias", r4, c4);
    float* W2 = load_param(root, "hidden_layer.weight", r2, c2);
    float* b2 = load_param(root, "hidden_layer.bias", r5, c5);
    float* W3 = load_param(root, "output_layer.weight", r3, c3);
    float* b3 = load_param(root, "output_layer.bias", r6, c6);

    std::vector<unsigned char> image;
    unsigned w, h;
    unsigned err = lodepng::decode(image, w, h, ipath);
    if (err) { fprintf(stderr, "png error %u: %s\n", err, lodepng_error_text(err)); return 1; }

    int N = (int)(w * h);
    float* x = new float[N];
    for (int i = 0; i < N; i++) {
        unsigned char pix = image[(size_t)i * 4 + 0];
        x[i] = (float)(((double)pix / 255.0 - 0.1307) / 0.3081);
    }

    float* h1 = new float[r1];
    float* h2 = new float[r2];
    float* out = new float[r3];

    linear(W1, b1, x, r1, c1, h1);
    for (int i = 0; i < r1; i++) h1[i] = relu(h1[i]);
    linear(W2, b2, h1, r2, c2, h2);
    for (int i = 0; i < r2; i++) h2[i] = relu(h2[i]);
    linear(W3, b3, h2, r3, c3, out);

    int pred = 0;
    for (int i = 1; i < r3; i++) if (out[i] > out[pred]) pred = i;

    printf("%d", pred);

    size_t sl = wpath.find_last_of('/');
    std::string dir = (sl == std::string::npos) ? std::string("./") : wpath.substr(0, sl + 1);
    std::string predp = dir + "prediction.txt";
    FILE* pf = fopen(predp.c_str(), "wb");
    if (pf) { fprintf(pf, "%d", pred); fclose(pf); }

    return 0;
}
